// Guías para padres. Base: orientaciones generales de la SPP, la OMS y el NHS.
// A REVER POR PROFISSIONAL DE SAÚDE
// PENDIENTE DE REVISIÓN POR UN PROFESIONAL SANITARIO
window.DiaryGuides = window.DiaryGuides || {};
window.DiaryGuides.es = [
  {"id": "ready", "title": "¿Está listo tu bebé para comer?", "intro": "La mayoría de los bebés están listos para los primeros alimentos hacia los 6 meses. Más que la edad exacta, importa observar las señales.", "sections": [
    {"h": "Señales de que está listo", "p": ["Busca estas señales en conjunto, y no solo una de ellas:"], "list": ["Se sienta con poco apoyo y mantiene la cabeza firme.", "Se lleva objetos y las manos a la boca con coordinación.", "Muestra interés por la comida: mira, se estira y abre la boca cuando ve comer a los demás.", "Ha perdido el reflejo de extrusión, es decir, ya no empuja la comida hacia fuera con la lengua."]},
    {"h": "Lo que no es una señal", "p": ["Algunos comportamientos son normales en el crecimiento y, por sí solos, no indican que el bebé necesite alimentos sólidos:"], "list": ["Despertarse por la noche.", "Querer mamar o tomar leche más veces.", "Morderse las manos o los puños."]},
    {"h": "Cuándo empezar", "p": ["Lo habitual es que esté listo hacia los 6 meses, pero cada bebé tiene su ritmo. Es el pediatra quien confirma el momento adecuado para tu bebé.", "Al principio, la leche materna o la fórmula siguen siendo el alimento principal. Las primeras comidas sirven para explorar sabores y texturas, sin prisa y sin presión."]},
    {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra antes de empezar, sobre todo si tu bebé nació prematuro, si tiene algún problema de salud o si tienes dudas sobre las señales."]}
  ]},
  {"id": "gagging", "title": "¿Arcadas o atragantamiento?", "intro": "Cuando el bebé aprende a comer, es normal que tenga arcadas. El atragantamiento es distinto y es una emergencia. Saber diferenciarlos te ayuda a reaccionar con calma.", "sections": [
    {"h": "Arcadas: normales y ruidosas", "p": ["Son un reflejo de protección que devuelve la comida a la parte delantera de la boca. Suelen ser ruidosas:"], "list": ["El bebé tose, hace ruidos o tiene arcadas.", "La cara puede ponerse roja y pueden llorarle los ojos.", "Mantén la calma, quédate a su lado y deja que lo resuelva solo."]},
    {"h": "Atragantamiento: peligro y silencio", "p": ["Ocurre cuando la comida bloquea las vías respiratorias. Las señales son distintas:"], "list": ["El bebé se queda en silencio o no puede llorar ni toser.", "Le cuesta respirar.", "Le cambia el color de la piel, que puede volverse pálida o azulada."]},
    {"h": "Qué hacer", "p": ["Si sospechas que se está atragantando, mantén la calma y llama de inmediato al número de emergencias. Sigue las indicaciones de quien te atienda.", "Esta app no enseña maniobras de primeros auxilios y no sustituye la formación. Todos los padres y cuidadores deberían hacer un curso práctico de primeros auxilios pediátricos antes de empezar la alimentación complementaria."]},
    {"h": "Cómo prevenir", "list": ["Sienta al bebé erguido, en una silla adecuada.", "Quédate siempre a su lado mientras come, sin distracciones.", "Nunca le des comida en la silla del coche, ni mientras camina, juega o está tumbado.", "Ofrece los alimentos en formas y texturas seguras para su edad, como se indica en cada alimento.", "Evita los alimentos duros, redondos o enteros, como los frutos secos y las uvas enteras."]},
    {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra si tu bebé tiene arcadas en casi todas las comidas, si rechaza las texturas de forma persistente o si te da miedo avanzar."]}
  ]},
  {"id": "textures", "title": "Texturas por edad", "intro": "Las texturas cambian a medida que el bebé aprende a masticar y a usar las manos. Las edades son solo una referencia.", "sections": [
    {"h": "Hacia los 6 meses", "p": ["Empieza con purés finos o con trozos blandos del largo de un dedo, que el bebé pueda agarrar. El alimento debe deshacerse con facilidad al apretarlo entre los dedos."]},
    {"h": "Hacia los 9 meses", "p": ["Pasa a alimentos aplastados con un tenedor, con algunos grumos, y a trozos pequeños y blandos. En esta etapa el bebé empieza a usar el pulgar y el índice en pinza para coger la comida."]},
    {"h": "Hacia los 12 meses", "p": ["El bebé puede comer la comida de la familia, picada o cortada en trozos pequeños, sin sal añadida. Es un buen momento para practicar con el tenedor y la cuchara, aunque se manche."]},
    {"h": "Avanzar al ritmo del bebé", "p": ["Avanzar desde los purés finos es importante: las texturas variadas ayudan al bebé a aprender a masticar y a aceptar alimentos nuevos. No te quedes mucho tiempo solo con purés finos.", "Cada bebé tiene su ritmo. Si rechaza una textura, vuelve a ofrecérsela otro día, con calma y sin forzar. El bebé come siempre sentado y vigilado."]},
    {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra si tu bebé rechaza todas las texturas con grumos, si tiene muchas arcadas o si tienes dudas sobre cómo avanzar."]}
  ]},
  {"id": "avoid", "title": "Alimentos que evitar el primer año", "intro": "Algunos alimentos no son seguros o adecuados para bebés menores de 12 meses. Esta lista es general y puede variar según el país.", "sections": [
    {"h": "No ofrecer", "list": ["Miel, en cualquier forma, antes de los 12 meses.", "Sal añadida, incluidos los caldos y los alimentos muy salados.", "Azúcar añadido, dulces y postres azucarados.", "Huevo, carne y pescado crudos o poco cocinados.", "Leche, queso y otros lácteos sin pasteurizar.", "Algunos pescados grandes, como el pez espada; pregunta al pediatra cuáles evitar."]},
    {"h": "Riesgo de atragantamiento", "p": ["Algunas formas y texturas son peligrosas, aunque el alimento en sí sea adecuado:"], "list": ["Frutos secos enteros o en trozos; ofrécelos solo molidos muy finos o en crema fina, en una capa muy fina.", "Alimentos duros enteros o en trozos grandes, como la zanahoria o la manzana crudas.", "Uvas enteras y alimentos redondos parecidos, como los tomates cherry; córtalos a lo largo, en cuartos."]},
    {"h": "Bebidas", "list": ["Leche de vaca como bebida principal antes de los 12 meses; puede usarse en pequeñas cantidades al cocinar.", "Té y café.", "Zumos, refrescos y otras bebidas azucaradas."]},
    {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra si tienes dudas sobre un alimento, sobre los alérgenos o sobre las recomendaciones de tu país."]}
  ]},
  {"id": "storage", "title": "Conservar, congelar y recalentar", "intro": "La comida del bebé requiere unos cuidados sencillos de higiene. Estos pasos te ayudan a prepararla y guardarla con seguridad.", "sections": [
    {"h": "Antes de cocinar", "list": ["Lávate bien las manos antes de preparar la comida y antes de dar de comer al bebé.", "Lava los utensilios, las tablas y las superficies.", "Lava la fruta y la verdura y cocina bien la carne, el pescado y el huevo."]},
    {"h": "Guardar y congelar", "list": ["Enfría la comida rápidamente y guárdala en la nevera en recipientes cerrados.", "Congela en porciones pequeñas, con la fecha anotada.", "Descongela en la nevera, y no a temperatura ambiente.", "Sigue los tiempos de conservación recomendados por la autoridad de seguridad alimentaria de tu país."]},
    {"h": "Recalentar y servir", "list": ["Recalienta hasta que la comida esté muy caliente y humeante en todo su interior.", "Después deja que se enfríe, remueve bien y comprueba la temperatura antes de servir.", "Recalienta solo una vez.", "Tira lo que sobre en el plato y todo lo que haya tocado la cuchara del bebé."]},
    {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra si tu bebé tiene vómitos o diarrea después de una comida, o si tienes dudas sobre la conservación de los alimentos."]}
  ]},
  {"id": "refusal", "title": "Cuando el bebé rechaza la comida", "intro": "Rechazar un alimento forma parte de aprender a comer. Casi nunca es un problema, y tu forma de reaccionar marca una gran diferencia.", "sections": [{"h": "Por qué ocurre", "p": ["Los sabores y las texturas nuevos le resultan extraños al bebé. Hacer muecas, escupir y girar la cara son reacciones normales y no significan que no le guste."], "list": ["Puede estar cansado, con sueño o sin hambre.", "Pueden estar saliéndole los dientes o puede estar malito.", "Puede que simplemente necesite más tiempo para acostumbrarse."]}, {"h": "Lo que ayuda", "list": ["Vuelve a ofrecerle el mismo alimento otro día, sin insistir. Muchos bebés solo aceptan un alimento después de probarlo varias veces.", "Prueba otra forma de prepararlo: cocido, asado, aplastado o en trozos.", "Junta un alimento nuevo con otro que al bebé ya le guste.", "Come al mismo tiempo que él. Los bebés aprenden mirando.", "Haz que las comidas sean tranquilas, sin pantallas y sin prisa."]}, {"h": "Lo que conviene evitar", "list": ["Forzar, insistir o meterle la cuchara cuando cierra la boca.", "Distraerlo con juguetes o pantallas para que coma.", "Usar la comida como premio o castigo.", "Renunciar a un alimento al primer rechazo."]}, {"h": "Quién decide qué", "p": ["Tú decides qué ofreces, cuándo y dónde. El bebé decide si come y cuánto come. Respetar sus señales de hambre y de saciedad le ayuda a tener una buena relación con la comida."]}, {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra si tu bebé rechaza casi todo durante varios días, si pierde peso o deja de ganarlo, si se atraganta o vomita con frecuencia, o si las comidas son siempre motivo de gran angustia."]}]},
  {"id": "water", "title": "Agua y otras bebidas", "intro": "Cuando el bebé empieza a comer, el agua pasa a formar parte de las comidas. La leche materna o la fórmula siguen siendo la bebida principal durante el primer año.", "sections": [{"h": "Agua", "list": ["Ofrécele agua en las comidas, a pequeños sorbos, desde el momento en que el bebé empieza a comer.", "Usa un vaso abierto pequeño o un vaso con pajita. Ayudan a aprender a beber y son mejores para los dientes que el biberón.", "Es normal que al principio derrame y beba poco. Está aprendiendo.", "Pregunta al pediatra si el agua del grifo de tu zona es adecuada para el bebé o si debes hervirla."]}, {"h": "Leche", "p": ["La leche materna o la fórmula siguen siendo la principal fuente de alimento y de líquidos durante el primer año. A medida que el bebé come más, va tomando menos leche, a su ritmo.", "La leche de vaca puede usarse en pequeñas cantidades en la comida, pero no debe ser la bebida principal antes de los 12 meses."]}, {"h": "Bebidas que evitar", "list": ["Zumos, incluso naturales, y néctares.", "Refrescos y bebidas con azúcar o edulcorantes.", "Té, café y otras bebidas con cafeína.", "Bebidas vegetales como sustituto de la leche, salvo indicación del pediatra."]}, {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra si tu bebé moja muchos menos pañales de lo habitual, si rechaza la leche o si tienes dudas sobre las cantidades."]}]},
  {"id": "routine", "title": "Rutina de las comidas", "intro": "No hay un horario adecuado para todos los bebés. Lo importante es empezar despacio, en un momento tranquilo, e ir aumentando al ritmo del bebé.", "sections": [{"h": "Al principio", "list": ["Empieza con una comida al día, en un momento en que el bebé esté despierto y de buen humor.", "Elige un momento en que no tenga mucha hambre ni mucho sueño. Darle un poco de leche antes puede ayudar.", "Bastan unas cucharadas o unos trozos. En esta etapa el objetivo es explorar, no llenar la barriga."]}, {"h": "Aumentar poco a poco", "p": ["Con el tiempo, el bebé pasa a hacer más comidas y a comer mayores cantidades. El ritmo varía mucho de un bebé a otro: sigue las indicaciones del pediatra y las señales de tu hijo."]}, {"h": "Señales de hambre y de saciedad", "list": ["Tiene hambre: se inclina hacia la comida, abre la boca, se agita cuando ve el plato.", "Está saciado: gira la cara, cierra la boca, aparta la cuchara, se distrae o juega con la comida.", "Cuando muestre que no quiere más, termina la comida sin insistir."]}, {"h": "En la mesa", "list": ["Sienta al bebé erguido, en una silla con reposapiés si es posible.", "Come con él siempre que puedas.", "Deja las pantallas y los juguetes para después.", "Cuenta con que se manchará: tocar la comida forma parte de aprender."]}, {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra si tienes dudas sobre el número de comidas o las cantidades para la edad de tu bebé."]}]},
  {"id": "cutting", "title": "Cómo cortar los alimentos con seguridad", "intro": "La forma y la textura de un alimento cuentan tanto como el alimento en sí. Unos cortes sencillos reducen mucho el riesgo de atragantamiento.", "sections": [{"h": "La regla de la textura", "p": ["Antes de servir, aprieta el alimento entre el pulgar y el índice. Si se aplasta con facilidad, el bebé puede aplastarlo con las encías."]}, {"h": "Para quien está empezando", "list": ["Corta en bastones largos, más o menos del tamaño de un dedo de adulto, para que el bebé los agarre con toda la mano.", "Cuece o asa las verduras y la fruta dura hasta que queden muy blandas.", "Deja parte de la piel en los alimentos resbaladizos, como el plátano o el aguacate, para que sea más fácil sujetarlos."]}, {"h": "Cuando ya hace la pinza", "p": ["Cuando el bebé empieza a coger cosas pequeñas entre el pulgar y el índice, puedes pasar a servirle trozos más pequeños y blandos."]}, {"h": "Alimentos redondos y duros", "list": ["Uvas, tomates cherry y otros alimentos redondos: córtalos a lo largo, en cuartos.", "Arándanos: aplástalos entre los dedos.", "Manzana y zanahoria crudas: cuécelas o rállalas.", "Frutos secos: nunca enteros ni en trozos. Úsalos molidos o en crema, untada en una capa fina.", "Quita siempre las espinas, los huesos, los huesos de la fruta y las pieles duras."]}, {"h": "Siempre", "list": ["El bebé come sentado y erguido, nunca gateando, caminando o en el coche.", "Quédate siempre a su lado mientras come.", "No le metas comida en la boca con los dedos: deja que sea él quien se la lleve."]}, {"h": "Cuándo hablar con el pediatra", "p": ["Habla con el pediatra si tu bebé se atraganta con frecuencia o le cuesta masticar y tragar."]}]}
];
